function [ dx ] = modelo_eq( t_out, x, ws, ks,ts,reg,ns,ne,te,n_s,n_c,ns_a,ts_frozen,points,tal,est,yi,utarg,tstarg,nstarg)
[u] = ver_reg_est1(ws,yi,t_out);
[uref] = ver_reg_est1(ws,yi,t_out);
mim = 0.53;
km = 1.2  ;
ki = 22   ;
Yx = 0.4  ;
Yp = 1    ;
v = 0.5   ;
Sin = 20  ;
xo = 1    ;
So = 0    ;
Po = 0    ;
Vo = 2;   ;
xmax= 3   ;
smax= 5   ;

y(1)=(mim*x(2) / (km + x(2)+ ( (x(2)^2)/ki )));

dx(1)=(y(1)*x(1) - u(1)*x(1)/x(4)                       )*tal;
dx(2)=(- y(1)*x(1)/Yx - v*x(1)/Yp + u(1)*(Sin-x(2))/x(4))*tal;
dx(3)=( v*x(1) - u(1)*x(3)/x(4)                         )*tal;
dx(4)=(u(1)                                             )*tal;
dx=transp(dx);
end                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
